from qbank_authoring import ref,finalize
TB=ref('CDC: Clinical and Laboratory Diagnosis of Tuberculosis','https://www.cdc.gov/tb/hcp/testing-diagnosis/clinical-and-laboratory-diagnosis.html')
HL=ref('Histiocyte Society: Recommendations for Adult HLH','https://doi.org/10.1182/blood.2018894618')
ST=ref('EULAR/PReS Recommendations: Diagnosis and Management of Still’s Disease, 2024','https://doi.org/10.1136/ard-2024-225851')
q('A 73-year-old has fever, new temporal headache, jaw claudication and transient monocular visual loss. What is the most appropriate action?', 'Urgently treat suspected giant cell arteritis and arrange confirmatory evaluation without delaying vision-protective therapy',[
 ('Wait for several weeks of negative cultures before treating','Threatened vision requires urgent action.'),('Treat a positive inflammatory marker alone as proof of bacterial infection','ESR and CRP are nonspecific.'),('Exclude vasculitis because fever preceded the headache','Systemic symptoms can precede cranial manifestations.')],
 'A noninfectious cause of fever can still be an emergency', '**Jaw claudication and ischemic visual symptoms strongly raise concern for GCA.**',['Urgent specialist assessment is required.','Threatened vision can justify intravenous pulse glucocorticoids.'], '**Obtain imaging or biopsy through an appropriate rapid pathway.**',['Do not defer treatment solely to preserve diagnostic yield when vision is threatened.','Reassess competing diagnoses and treatment toxicity.'],[['Clue','Cranial ischemic symptoms'],['Risk','Irreversible visual loss'],['Priority','Urgent treatment plus confirmation']],[GC],style='clinical_scenario')
q('Fever begins after a new medicine, with no identified infection and a compatible temporal course. Which statement about drug fever is correct?', 'It is considered after evaluating alternatives, and improvement after safe withdrawal supports the diagnosis',[
 ('Eosinophilia is mandatory in every case','Its absence does not exclude drug fever.'),('Relative bradycardia alone establishes the diagnosis','Pulse-temperature relationships are not sufficiently specific.'),('A deliberate rechallenge is routinely required','Re-exposure may be unsafe and is not routinely necessary.')],
 'Medication exposure is part of every fever history', '**Drug fever can occur without a rash or eosinophilia.**',['Review prescribed, nonprescription and recently stopped medicines.','Distinguish uncomplicated fever from severe systemic drug hypersensitivity.'], '**Withdraw a suspected nonessential agent safely and observe the course.**',['Maintain treatment for other established conditions.','Organ injury, mucosal lesions or systemic deterioration require a broader urgent evaluation.'],[['Temporal relationship','Raises suspicion'],['Dechallenge','Supports causality'],['Rash or eosinophilia','May be absent']],[IC],style='clinical_scenario')
q('An adult with prolonged fever has ferritin 18,000 ng/mL. What is the most accurate conclusion?', 'Severe hyperferritinemia raises concern for HLH and other inflammatory, hepatic or malignant conditions but is not diagnostic alone',[
 ('The value independently proves HLH in every adult','Adult specificity is insufficient.'),('It excludes infection because ferritin is an iron marker','Infection can trigger marked inflammation and HLH.'),('It establishes hereditary hemochromatosis as the cause of fever','Ferritin is an acute-phase marker as well as an iron-storage marker.')],
 'A striking marker should trigger structured assessment rather than diagnostic closure', '**HLH evaluation integrates fever, cytopenias, organ findings and additional tests.**',['Assess triglycerides, fibrinogen, liver function and relevant specialist studies.','Look for an infectious, malignant or inflammatory trigger.'], '**Treat organ-threatening illness while the diagnostic process continues.**',['Absence of hemophagocytosis does not exclude HLH.','Adult assessment requires clinical interpretation rather than one laboratory cutoff.'],[['Ferritin','Important but nonspecific'],['HLH','Integrated clinical and laboratory syndrome'],['Cause','Search for the underlying trigger']],[HL],style='clinical_scenario')
q('An adult has quotidian fever, an evanescent salmon-colored rash, inflammatory arthritis and high ferritin. Which diagnostic principle is most appropriate?', 'Consider Still’s disease after a structured assessment for infectious, malignant and other inflammatory mimics',[
 ('Ferritin alone definitively confirms Still’s disease','It is not a disease-specific diagnostic test.'),('A positive rheumatoid factor is required','That is not a mandatory defining feature.'),('Any salmon-colored rash excludes infection without testing','Clinical mimics still require assessment.')],
 'A characteristic inflammatory pattern needs exclusion of important mimics', '**Still’s disease can produce fever, rash, arthritis and systemic inflammation.**',['No single routine test establishes the diagnosis.','Macrophage activation syndrome is an important complication.'], '**Use an integrated diagnostic and treatment pathway.**',['Assess cultures and targeted infection studies according to risk.','New cytopenias, falling fibrinogen or organ failure can signal a complication.'],[['Pattern','Fever, evanescent rash and arthritis'],['Ferritin','Supportive, nonspecific'],['Complication','Macrophage activation syndrome']],[ST],style='clinical_scenario')
q('A patient has prolonged fever, unpasteurized dairy exposure and sacroiliac pain. What additional diagnostic action is important when brucellosis is suspected?', 'Notify the laboratory of the suspicion while arranging appropriate culture and serology',[
 ('Send unlabeled cultures without exposure information','Laboratory aerosol risk and specialized handling matter.'),('Use a Widal test as the specific Brucella assay','Widal tests concern Salmonella antigens and are not the relevant diagnostic method.'),('Exclude infection because the fever fluctuates','Brucellosis can have an intermittent or undulating course.')],
 'An exposure history can affect both diagnosis and laboratory safety', '**Brucella can cause prolonged fever and osteoarticular disease.**',['Unpasteurized dairy and animal exposure are important clues.','Laboratory handling of suspected organisms can create aerosol exposure risk.'], '**Alert microbiology and use appropriate targeted tests.**',['Culture and serology are interpreted with exposure and prior therapy.','Assess focal complications rather than treating the fever pattern alone.'],[['Exposure','Unpasteurized dairy or animals'],['Focal clue','Osteoarticular pain'],['Laboratory','Advance notification and safe handling']],[BR],style='clinical_scenario')
q('A livestock worker has acute fever and hepatitis after exposure to animal birth products. Initial Q-fever serology is negative during the first week. Which approach is best?', 'Use early PCR and paired serology as appropriate; a negative early antibody test does not exclude Q fever',[
 ('Exclude Q fever permanently because the first antibody test is negative','Antibodies often appear later.'),('Request routine culture without special laboratory discussion','Routine culture is not the recommended diagnostic method.'),('Wait for seroconversion before treating a strongly suspected clinically important infection','Treatment should not be withheld pending confirmation.')],
 'Antibody and molecular detection have different diagnostic windows', '**Coxiella burnetii can be acquired by inhalation of contaminated animal aerosols.**',['PCR is most useful early, before or soon after treatment.','Paired antibody testing can document the evolving response.'], '**Interpret the result with illness timing and exposure.**',['A single early negative result is weak exclusion evidence.','Assess persistent focal infection risk when relevant.'],[['Early illness','PCR can help'],['Serology','May initially be negative'],['Clinical decision','Do not await confirmation when treatment is indicated']],[QF],style='clinical_scenario')
q('A patient in an endemic setting has prolonged fever and one positive Widal test. Which diagnostic strategy is most appropriate for suspected enteric fever?', 'Obtain blood cultures and interpret the syndrome and resistance risk rather than treating Widal positivity as definitive',[
 ('Diagnose typhoid solely from the Widal result','False positives and background antibodies limit reliability.'),('Use a negative Widal test to exclude all enteric fever','Sensitivity and specificity are inadequate.'),('Select antibiotics without considering travel or local resistance','Resistance patterns materially affect treatment.')],
 'Enteric fever needs microbiological confirmation when feasible', '**Blood culture is the principal routine diagnostic method.**',['Multiple cultures can improve recovery.','Prior antibiotics may lower sensitivity.'], '**Use susceptibility and exposure information for treatment.**',['A serological label must not obscure another cause of fever.','Public health and food-handling considerations may be relevant.'],[['Blood culture','Mainstay of diagnosis'],['Widal','Not a definitive diagnostic test'],['Therapy','Resistance-informed selection']],[TY],style='clinical_scenario')
q('A patient with fever, weight loss and a suggestive chest image has a positive IGRA. What does the IGRA establish?', 'Immunological evidence of TB infection; it does not by itself distinguish latent infection from active disease',[
 ('Active pulmonary TB is confirmed without further assessment','Active disease requires clinical and appropriate microbiological evaluation.'),('The organism is susceptible to rifampicin','IGRA does not determine drug susceptibility.'),('The patient is definitely infectious regardless of disease site','Infectiousness depends on active disease characteristics.')],
 'TB infection testing and TB disease diagnosis answer different questions', '**IGRA measures an immune response to selected mycobacterial antigens.**',['It does not directly detect viable bacilli.','A negative immune test also cannot reliably exclude active disease in every patient.'], '**Investigate suspected active disease with suitable specimens and imaging.**',['Use appropriate infection-control precautions for possible pulmonary disease.','Obtain molecular, smear and culture studies according to the pathway.'],[['IGRA','Evidence of infection'],['Active disease','Clinical and microbiological assessment'],['Resistance','Separate organism-based testing']],[TB],style='clinical_scenario')
q('An asplenic adult develops abrupt fever and rigors with no clear focus. Which management principle is most appropriate?', 'Arrange urgent clinical assessment and prompt empirical antibiotics according to the asplenia emergency plan',[
 ('Observe at home for three days because there is no focal symptom','Overwhelming infection can progress rapidly without a clear early focus.'),('Assume vaccination eliminates the possibility of invasive infection','Vaccines reduce risk but do not eliminate it.'),('Wait for blood-culture confirmation before treatment','This can create a dangerous delay.')],
 'Loss of splenic function changes the urgency of fever assessment', '**Rapid invasive infection, including encapsulated bacteria, is a major risk.**',['Patients need education and a clear emergency plan.','Vaccination and selected prophylaxis complement urgent assessment.'], '**Collect cultures if feasible without delaying therapy.**',['Escalate immediately for hypotension or organ dysfunction.','Review preventive care after recovery.'],[['Asplenia','Higher invasive-infection risk'],['Fever','Urgent action'],['Prevention','Vaccines, education and individualized prophylaxis']],[SP],style='clinical_scenario')
q('A patient with an indwelling urinary catheter has new fever and a positive urine culture. Which interpretation is best?', 'Bacteriuria is common with catheters; assess urinary evidence and alternative sources rather than assigning causality from culture alone',[
 ('Every positive catheter urine culture proves the source of fever','Colonization is common.'),('Catheter-associated UTI is impossible without dysuria','Symptoms may be difficult to assess and presentation can vary.'),('A positive culture excludes pneumonia or line infection','More than one process or an alternative source may exist.')],
 'Detection at a colonized site is not the same as infection', '**Catheter exposure increases asymptomatic bacteriuria.**',['Urinary findings and the clinical syndrome determine interpretation.','Pyuria alone is also not a universal proof of symptomatic infection.'], '**Look for a coherent source and address the device when indicated.**',['Obtain a suitable specimen through the recommended collection method.','Avoid treating colonization while missing the actual fever cause.'],[['Culture','Organism detection'],['Clinical syndrome','Determines likely infection'],['Source assessment','Include other sites and device management']],[IC],style='clinical_scenario')
q('Why can a broad multiplex molecular panel return a positive result that does not explain the patient’s fever?', 'It may detect colonization, prolonged shedding or nucleic acid without proving active causal disease',[
 ('Molecular detection always establishes viable invasive infection','It does not universally establish viability or causality.'),('All molecular tests have identical specificity and clinical meaning','Performance depends on the assay, specimen and organism.'),('A positive panel eliminates the need to assess the patient','Clinical integration remains essential.')],
 'Analytical detection and clinical causation are distinct', '**The meaning of a result depends on the sampled site and pretest probability.**',['An unexpected low-probability finding may need confirmation.','A negative limited panel does not exclude organisms outside its targets.'], '**Choose a test that matches the syndrome.**',['Discuss difficult findings with microbiology.','Avoid extending treatment solely because residual nucleic acid remains detectable.'],[['Positive','Target nucleic acid detected'],['Causation','Requires clinical integration'],['Negative','Limited to assay targets and sensitivity']],[LA])
q('A patient has recurrent fever with rigors, but the precise periodic pattern does not match a textbook description. What is the best principle?', 'Use the pattern as a clue while prioritizing exposure, severity and confirmatory testing',[
 ('Exclude malaria unless a perfect tertian pattern is documented','Early malaria often lacks a classic periodic pattern.'),('Diagnose brucellosis from any undulating temperature chart alone','The pattern is not specific.'),('Use antipyretic response to distinguish bacterial from malignant fever reliably','Response is not an etiological test.')],
 'Temperature patterns rarely provide a complete diagnosis', '**Classical fever patterns can be absent or altered by treatment.**',['Rigors raise concern for bloodstream infection but are not organism-specific.','Accurate objective measurement remains useful.'], '**Follow the risk-based diagnostic pathway.**',['Do not delay cultures or malaria testing while waiting for a pattern.','Reassess as new clinical evidence appears.'],[['Fever pattern','Supporting clue'],['Etiology','Exposure and targeted tests'],['Urgency','Determined by clinical risk']],[MA,LA])

